const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const mayfield = ee.Geometry.Point([-88.6338, 36.7401]);
    const collection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG');

    // 2. Data Acquisition
    // Period 1: November 2021 (pre-tornado)
    const nov2021 = collection.filterDate('2021-11-01', '2021-11-30').first();

    // Period 2: December 2021 (post-tornado)
    // The monthly composite for December will reflect the state after the Dec 10th tornado.
    const dec2021 = collection.filterDate('2021-12-01', '2021-12-31').first();

    // 3. Data Availability Check
    const nov2021_size = ee.Algorithms.IsEqual(nov2021, null).not();
    const dec2021_size = ee.Algorithms.IsEqual(dec2021, null).not();

    if (!nov2021_size.getInfo() || !dec2021_size.getInfo()) {
        console.log(`Data found for Nov 2021: ${nov2021_size.getInfo()}`);
        console.log(`Data found for Dec 2021: ${dec2021_size.getInfo()}`);
        console.log("C1: Empty Collection");
        return;
    }

    // 4. Processing & Calculation
    const band = 'avg_rad';
    const scale = 500; // Native resolution is ~500m

    // Extract average radiance value for November 2021
    const nov_brightness_dict = nov2021.select(band).reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: mayfield.buffer(500), // Buffer to get a small area average
        scale: scale,
        maxPixels: 1e9
    });

    // Extract average radiance value for December 2021
    const dec_brightness_dict = dec2021.select(band).reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: mayfield.buffer(500),
        scale: scale,
        maxPixels: 1e9
    });

    const nov_brightness = ee.Number(nov_brightness_dict.get(band));
    const dec_brightness = ee.Number(dec_brightness_dict.get(band));

    // 5. Validation & Final Answer
    const nov_val = nov_brightness.getInfo();
    const dec_val = dec_brightness.getInfo();

    if (nov_val === null || dec_val === null) {
        console.log(`November 2021 Value: ${nov_val}`);
        console.log(`December 2021 Value: ${dec_val}`);
        console.log("C3: Calculation Failure");
        return;
    }

    console.log(`November 2021 Brightness (avg_rad): ${nov_val.toFixed(2)}`);
    console.log(`December 2021 Brightness (avg_rad): ${dec_val.toFixed(2)}`);

    if (nov_val > dec_val) {
        console.log("Evidence: Nighttime brightness was higher in November 2021.");
        console.log("A");
    } else {
        console.log("Evidence: Nighttime brightness was not higher in November 2021.");
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error(e);
        console.log("D");
    }
}

initEE();
